import{_ as e,o as t,c as i,a3 as l}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"萌新指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),o={name:"guide/index.md"};function r(s,a,d,n,c,p){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="萌新指南" tabindex="-1">萌新指南 <a class="header-anchor" href="#萌新指南" aria-label="Permalink to &quot;萌新指南&quot;">​</a></h1><p>欢迎来到无限工程。这里的内容会帮助你从第一次进入服务器开始，逐步熟悉服务器环境与基础玩法。</p><h2 id="开始游戏" tabindex="-1">开始游戏 <a class="header-anchor" href="#开始游戏" aria-label="Permalink to &quot;开始游戏&quot;">​</a></h2><p>请先确认 Minecraft 客户端、NeoForge 版本和服务器整合包与公告要求一致。具体下载方式与连接地址将在服务器公开后在本页补充。</p><div class="tip custom-block"><p class="custom-block-title">建议</p><p>第一次进入前，建议先完整阅读 <a href="/rules/">服务器规则</a>；它比任何单一教程都更重要。</p></div><h2 id="进入服务器" tabindex="-1">进入服务器 <a class="header-anchor" href="#进入服务器" aria-label="Permalink to &quot;进入服务器&quot;">​</a></h2><ol><li>使用公告指定的客户端与模组配置启动游戏。</li><li>在多人游戏界面添加服务器地址（待公布）。</li><li>初次进入后，按聊天栏或新手任务的引导完成基础设置。</li></ol><h2 id="前期目标" tabindex="-1">前期目标 <a class="header-anchor" href="#前期目标" aria-label="Permalink to &quot;前期目标&quot;">​</a></h2><p>前期不必急于追赶进度。建议先建立安全据点、整理资源并熟悉任务线，再选择科技或魔法方向深入发展。</p><h2 id="基础指令" tabindex="-1">基础指令 <a class="header-anchor" href="#基础指令" aria-label="Permalink to &quot;基础指令&quot;">​</a></h2><p>服务器可用指令、权限范围及使用示例将在功能确认后补充。请勿依赖来源不明的指令说明。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>如遇卡顿、物品丢失或异常，请保留发生时间、所在维度与必要截图，便于管理人员排查。</p></div>',12)])])}const _=e(o,[["render",r]]);export{u as __pageData,_ as default};
